import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/schueler/datenschutzhinweis.png",a="/bilder/schueler/datenschutz-links-datenschutzkonzept.png",m=JSON.parse('{"title":"Datenschutzhinweise und Löschpflichten nachschlagen","description":"","frontmatter":{"title":"Datenschutzhinweise und Löschpflichten nachschlagen","source_pageid":406,"source_revision":5304},"headers":[],"relativePath":"schild3/schueler/datenschutzhinweise-verwaltung-hilfe.md","filePath":"schild3/schueler/datenschutzhinweise-verwaltung-hilfe.md"}'),h={name:"schild3/schueler/datenschutzhinweise-verwaltung-hilfe.md"};function u(l,e,d,c,o,g){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="datenschutzhinweise-und-loschpflichten-nachschlagen" tabindex="-1">Datenschutzhinweise und Löschpflichten nachschlagen <a class="header-anchor" href="#datenschutzhinweise-und-loschpflichten-nachschlagen" aria-label="Permalink to &quot;Datenschutzhinweise und Löschpflichten nachschlagen&quot;">​</a></h1><p>Lesen Sie die beim Programmstart angezeigten Datenschutzhinweise und die Verweise zum Umgang mit Schüler- und Lehrkräftedaten. Der Artikel erläutert auch die Bedeutung von Aufbewahrung und Löschung.</p><p><a href="/bilder/schueler/datenschutzhinweis.png"><img src="'+s+'" alt="Beim Systemstart wird beim Login der Datenschutzhinweis angezeigt (Stand: März 2024)." loading="lazy"></a></p><p><em>Beim Systemstart wird beim Login der Datenschutzhinweis angezeigt (Stand: März 2024).</em></p><p>Bei jedem Systemstart wird im Loginscreen der Datenschutzhinweis angezeigt. Die Kenntnisnahme ist mit <strong>OK</strong> zu bestätigen.</p><p>Ein Klick auf <strong>Abbrechen</strong> führt zum Programmende.</p><p>Die automatische Verarbeitung von personenbezogenen Daten unterliegt konkreten Bestimmungen, die in NRW in den Verordnungen zur Verarbeitung elektronischer Daten beschrieben sind.</p><ul><li><p>Dabei legt die <em>VO-DV I</em> fest, welche <em>Schülerdaten</em> verwaltet werden dürfen und wie diese Verwaltung auszusehen hat.</p></li><li><p>Die Speicherung der <em>Lehrerdaten</em> wird von der <em>VO-DV II</em> geregelt.</p></li></ul><p>Bitte informieren Sie sich über die Art und Anzahl der Daten, die verwaltet werden dürfen, und halten Sie auch deren Löschungsfristen ein.</p><p>Beachten Sie dabei bitte auch die Anbietungspflicht an die zuständigen Archive nach § 4 Abs. 1 und 2 i.V.m. § 10 Abs. 5 ArchivG NRW.</p><p>Die Datenschutzbeauftragen der Schulen, das können auch kommunal bestellte Personen sein, sind in der Regel mit der Erstellung eines Verfahrensverzeichnisses für die verwendete Software beauftragt.</p><p><a href="/bilder/schueler/datenschutz-links-datenschutzkonzept.png"><img src="'+a+'" alt="Informationen zum Datenschutz auf der Seite des MSB für Schulverwaltungssoftware. Stand März 2024." loading="lazy"></a></p><p><em>Informationen zum Datenschutz auf der Seite des MSB für Schulverwaltungssoftware. Stand März 2024.</em></p><p>Auf der Seite für <a href="https://www.svws.nrw.de/links/" target="_blank" rel="noreferrer">Schulverwaltungssoftware des MSB</a> findet sich unter dem Punkt <strong>Links</strong> der Punkt <strong>Datenschutzkonzept</strong>.</p><p>Unter diesem findet sich eine Zusammenstellung von Informationen und Hinweisen wie</p><ul><li>Hinweise zur DSGVO</li><li>Links auf die VO-DV-I und VO-DV-II</li><li>Muster für Verarbeitungsverzeichnisse</li></ul><p>und mehr.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Datenschutzhinweise_(Verwaltung_Hilfe)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5304.</p>',19)])])}const f=n(h,[["render",u]]);export{m as __pageData,f as default};
